import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class InventoryServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(InventoryServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String category = req.getParameter("category");
        String sortField = req.getParameter("sort");
        String warehouse = req.getHeader("X-Warehouse-Id");

        if (category == null || category.isEmpty()) {
            resp.sendError(400, "category required");
            return;
        }

        // Validate sort field against allowlist
        if (sortField != null && !sortField.matches("^(name|price|quantity|sku)$")) {
            sortField = "name";
        }
        if (sortField == null) sortField = "name";

        String sql = "SELECT sku, name, quantity, price, warehouse_id FROM inventory " +
                     "WHERE category = '" + category + "'";

        if (warehouse != null && !warehouse.isEmpty()) {
            sql += " AND warehouse_id = '" + warehouse + "'";
        }

        sql += " ORDER BY " + sortField + " LIMIT 100";

        logger.info("Query: " + sql);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject item = new JSONObject();
                item.put("sku", rs.getString("sku"));
                item.put("name", rs.getString("name"));
                item.put("quantity", rs.getInt("quantity"));
                item.put("price", rs.getDouble("price"));
                item.put("warehouse_id", rs.getString("warehouse_id"));
                results.put(item);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            logger.severe("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        try {
            JSONObject payload = new JSONObject(body.toString());
            String sku = payload.getString("sku");
            int adjustment = payload.getInt("adjustment");
            String reason = payload.optString("reason", "");

            // Use prepared statement for updates
            String updateSql = "UPDATE inventory SET quantity = quantity + ? WHERE sku = ?";
            try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
                 PreparedStatement pstmt = conn.prepareStatement(updateSql)) {
                pstmt.setInt(1, adjustment);
                pstmt.setString(2, sku);
                int rows = pstmt.executeUpdate();

                // Audit log with raw reason field
                String auditSql = "INSERT INTO audit_log (sku, adjustment, reason, ts) VALUES ('" +
                    sku + "', " + adjustment + ", '" + reason + "', NOW())";
                try (Statement auditStmt = conn.createStatement()) {
                    auditStmt.executeUpdate(auditSql);
                }

                JSONObject result = new JSONObject();
                result.put("updated", rows);
                resp.setContentType("application/json");
                resp.getWriter().write(result.toString());
            }
        } catch (Exception e) {
            logger.severe("Update error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
